const fs = require('fs');

function solve() {
    const data = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
    if (data.length === 0) return;
    const n = data[0];
    const k = data[1];
    const MOD = 777777777;

    // Precompute factorials and inverse factorials
    const fact = new Array(n + 1).fill(1);
    for (let i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    const invFact = new Array(n + 1).fill(1);
    // Fermat's little theorem for inverse: a^(p-2) mod p. MOD is not prime, so use extended Euclid or precompute invs.
    // Since n <= 28, we can compute combinations using Pascal's triangle or simple multiplicative formula with BigInt if needed,
    // but modulo is 777777777 = 3^2 * 7 * 11 * 13 * 37 * 101? Let's check.
    // 777777777 = 3 * 259259259 = 3 * 3 * 86419753 = 9 * 86419753.
    // 86419753 = 7 * 12345679 = 7 * 37 * 333667? 
    // Actually 777777777 = 3^2 * 7 * 11 * 13 * 37 * 101 * 9901? No.
    // Let's just compute C(n, k) using DP or multiplicative formula with modulo.
    // Since n <= 28, we can compute exact integer value of C(n,k) then take modulo.
    // Max C(28, 14) = 40116600 < 2^31, fits in standard JS Number exactly.

    function C(nn, kk) {
        if (kk < 0 || kk > nn) return 0;
        if (kk > nn - kk) kk = nn - kk;
        let res = 1;
        for (let i = 1; i <= kk; i++) {
            res = res * (nn - kk + i) / i;
        }
        return res % MOD;
    }

    // Precompute powers: pow[x][y] = x^y % MOD for x, y up to n.
    const pow = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(1));
    for (let x = 0; x <= n; x++) {
        for (let y = 1; y <= n; y++) {
            pow[x][y] = (pow[x][y - 1] * x) % MOD;
        }
    }

    let ans = 0;
    // t is the actual number of truth-tellers.
    for (let t = 0; t <= n; t++) {
        const L = n - t; // Actual number of liars
        if (L !== k) continue;

        // Number of ways to choose which t people are truth-tellers: C(n, t)
        const waysChoose = C(n, t);

        // The t truth-tellers must all answer 't'. (1 way)
        // The L liars must each answer an integer in [1, n] \ {t}.
        // Number of choices per liar: n - 1.
        // Total ways for liars' answers: (n - 1)^L.
        const waysLiars = pow[n - 1][L];

        const totalWays = (waysChoose * waysLiars) % MOD;
        ans = (ans + totalWays) % MOD;
    }

    console.log(ans);
}

